# ---- every turn ----
# tunables: round the monolith plan starts, and health fraction needed to fight for it
keep mono_start = 1000
keep mono_min = 0.6
keep camp_spawns = camp_spawn_tiles()
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep monos = monolith_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 3 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 30% health: toward spawn when in danger, otherwise recall
if not at_spawn and health() < 0.3 * max_health():
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not in_danger():
    recall()
    end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 10 or round_number() > 1500 or health() < 0.5 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for all attack checks
let camps = camps_visible()

# attacks any camp in range, including a monolith we are already next to (casts too)
let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    end_turn()

# ---- late team monolith plan ----
let mono = closest(monos)
if round_number() > mono_start and exists(mono):
    # hurt: drop the claim and heal on spawn before rejoining
    if health() < mono_min * max_health():
        unclaim()
        if not at_spawn:
            move_towards( closest( spawn_region(ally()) ) )
        end_turn()
    # monolith dead and cleared: stand on its spawn to capture it
    if contains(capturable_spawns(), mono):
        move_towards(mono)
        end_turn()
    claim(mono)
    let n_others = claim_count(mono)
    # commit with two other claimants, or with one when we are already close
    if n_others >= 2 or (n_others >= 1 and distance(position(), mono) <= 6):
        move_towards(mono)
        end_turn()
    # gather at spawn (heals there); also the abandon path when attackers fall below 2
    if at_spawn:
        end_turn()
    move_towards( closest( spawn_region(ally()) ) )
    end_turn()
else:
    unclaim()

# nothing tributed by round 300 (only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 300:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# on a dead camp of a group not yet cleared, walk to the nearest living camp (not monolith/golem)
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# tunable: dash toward a camp goal only when it is farther than this
if exists(goal) and distance(position(), goal) > 4:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v2: v1 (vendetta, vesper_vale, tavi, ryth, ren draft; ability-type-aware casting; retreat/recall;
# capture holds) with a sturdier team monolith plan.
# Changes from v1:
#  - hysteresis on the monolith fight: a champion that is already within 6 of the monolith keeps
#    fighting down to hold_hp (35%) instead of walking away at commit_hp (60%). Entering still needs 60%.
#  - commit needs 2+ other claimers OR 2+ allies within 6, so a half-formed group still goes in.
#  - a claim is dropped when no claimers and no allies are near (fewer than 2 attackers).
#  - low-health retreat and recall (generic block above) still run first, so champions pull back
#    individually and heal on spawn.
# Maps without monoliths play as v1.

# zg14: ability-type-aware casting: shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

