# ---- late monolith plan (starts at mono_start) ----
# every champion in the window claims the nearest free monolith (so claim_count sees the others).
# It commits as a group: 2+ other claimers or 2+ allies within 6. Entering needs commit_hp;
# a champion already within 6 of the monolith keeps going down to hold_hp.
# Below that it recalls or farms normally. With no claimers and no allies near it drops the claim.
if round_number() > mono_start and count(monos) > 0:
    let mt = closest( minus( monos, respawning_visible_spawns() ) )
    if exists(mt):
        claim(mt)
        let group_here = allies_within(6)
        let group_claims = claim_count(mt)
        let near_mt = distance(position(), mt) <= 6
        let hp_ok = health() >= commit_hp * max_health() or (near_mt and health() >= hold_hp * max_health())
        if hp_ok and (group_claims >= 2 or group_here >= 2):
            # standing on the cleared monolith spawn: hold so the 5-round capture timer runs
            if distance(position(), mt) == 0:
                end_turn()
            move_towards(mt)
            end_turn()
        if group_claims == 0 and group_here == 0:
            unclaim()
    else:
        unclaim()

