let risky = exists(goal0) and group_threat(goal0) * group_hp(goal0) / (my_dps * (1 + allies_within(4))) > health()
if risky:
    let alt = closest( minus( goals, filter( goals, within(0, goal0) ) ) )
    if exists(alt):
        move_towards(alt)
        end_turn()

let goal = goal0
# on a dead camp of a group that is not cleared yet, the closest goal is our own tile: walk to the
# nearest living camp instead (not a monolith or golem), so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a camp goal only when it is farther than 4
if exists(goal) and distance(position(), goal) > 4:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
